function flipEvenGroups(head: ListNode | null): ListNode | null {
  const vals: number[] = [];
  for (let p = head; p; p = p.next) vals.push(p.val);
  for (let start = 0, size = 1; start < vals.length; start += size, size++) {
    const end = Math.min(start + size, vals.length);
    if ((end - start) % 2 === 0) {
      for (let i = start, j = end - 1; i < j; i++, j--) [vals[i], vals[j]] = [vals[j], vals[i]];
    }
  }
  let i = 0;
  for (let p = head; p; p = p.next) p.val = vals[i++];
  return head;
}

