class Solution:
    def flipEvenGroups(self, head: Optional[ListNode]) -> Optional[ListNode]:
        vals = []
        p = head
        while p:
            vals.append(p.val)
            p = p.next
        start, size = 0, 1
        while start < len(vals):
            end = min(start + size, len(vals))
            if (end - start) % 2 == 0:
                vals[start:end] = vals[start:end][::-1]
            start, size = end, size + 1
        p, i = head, 0
        while p:
            p.val = vals[i]
            p, i = p.next, i + 1
        return head

