function flipEvenGroups(head: ListNode | null): ListNode | null {
  let prev = head!; // the first group has length 1 and never flips
  for (let size = 2; prev.next; size++) {
    let len = 0, after: ListNode | null = prev.next;
    while (after && len < size) { after = after.next; len++; }
    if (len % 2 === 0) {
      const first = prev.next!;
      let cur: ListNode | null = first, back: ListNode | null = after;
      for (let k = 0; k < len; k++) {
        const nx: ListNode | null = cur!.next;
        cur!.next = back;
        back = cur;
        cur = nx;
      }
      prev.next = back;
      prev = first;
    } else {
      for (let k = 0; k < len; k++) prev = prev.next!;
    }
  }
  return head;
}

