class Solution:
    def flipEvenGroups(self, head: Optional[ListNode]) -> Optional[ListNode]:
        prev = head  # the first group has length 1 and never flips
        size = 2
        while prev.next:
            length, after = 0, prev.next
            while after and length < size:
                after = after.next
                length += 1
            if length % 2 == 0:
                first = prev.next
                cur, back = first, after
                for _ in range(length):
                    cur.next, back, cur = back, cur, cur.next
                prev.next = back
                prev = first
            else:
                for _ in range(length):
                    prev = prev.next
            size += 1
        return head

